// stores/{domain}Store.ts
import type { {Domain}, {Domain}Paginated } from '~/types/{Domain}'

export const use{Domain}Store = defineStore('{domain}', {
  state: () => ({
    items:       [] as {Domain}[],
    currentItem: null as {Domain} | null,
    loading:     false,
    error:       null as string | null,
    meta: {
      total:       0,
      page:        1,
      per_page:    10,
      total_pages: 0
    }
  }),

  getters: {
    totalPages: (state): number => state.meta.total_pages,
    isEmpty:    (state): boolean => state.items.length === 0 && !state.loading
  },

  actions: {
    setList(data: {Domain}Paginated) {
      this.items = data.{domain}s
      this.meta  = data.meta
    },
    setCurrentItem(item: {Domain} | null) {
      this.currentItem = item
    },
    setLoading(val: boolean) {
      this.loading = val
    },
    setError(msg: string | null) {
      this.error = msg
    },
    removeItem(id: number) {
      this.items = this.items.filter(i => i.id !== id)
      this.meta.total--
    }
  }
})

// composables/useNotification.ts
type NotificationType = 'success' | 'error' | 'warning' | 'info'

const state = reactive({
  show:    false,
  message: '',
  type:    'success' as NotificationType,
  timeout: 3000
})

export const useNotification = () => {
  const notify = (message: string, type: NotificationType = 'success', timeout = 3000) => {
    state.message = message
    state.type    = type
    state.timeout = timeout
    state.show    = true
  }

  const success = (message: string) => notify(message, 'success')
  const error   = (message: string) => notify(message, 'error')
  const warning = (message: string) => notify(message, 'warning')

  return { state, notify, success, error, warning }
}
