// tests/e2e/fixtures/test-helpers.ts
import type { APIRequestContext } from '@playwright/test'

export async function createViaApi(
  request: APIRequestContext,
  endpoint: string,
  data: Record<string, unknown>
) {
  const response = await request.post(`/api${endpoint}`, { data })
  if (!response.ok()) {
    throw new Error(`API error ${response.status()}: ${await response.text()}`)
  }
  return response.json()
}

export async function deleteViaApi(
  request: APIRequestContext,
  endpoint: string,
  id: number
) {
  await request.delete(`/api${endpoint}/${id}`)
}

export async function loginAs(
  request: APIRequestContext,
  email: string,
  password: string
) {
  const response = await request.post('/api/auth/login', { data: { email, password } })
  return response.json()
}

// tests/e2e/pages/login.page.ts
import type { Page, Locator } from '@playwright/test'
import { expect } from '@playwright/test'

export class LoginPage {
  readonly page:          Page
  readonly emailInput:    Locator
  readonly passwordInput: Locator
  readonly submitButton:  Locator
  readonly errorToast:    Locator

  constructor(page: Page) {
    this.page          = page
    this.emailInput    = page.getByLabel('Email')
    this.passwordInput = page.getByLabel('Mot de passe')
    this.submitButton  = page.getByRole('button', { name: 'Se connecter' })
    this.errorToast    = page.locator('.v-snackbar')
  }

  async goto() { await this.page.goto('/login') }

  async login(email: string, password: string) {
    await this.emailInput.fill(email)
    await this.passwordInput.fill(password)
    await this.submitButton.click()
  }

  async expectError(message: string) {
    await this.errorToast.waitFor({ state: 'visible' })
    await expect(this.errorToast).toContainText(message)
  }
}

// tests/e2e/pages/{domain}s.page.ts
import type { Page, Locator } from '@playwright/test'
import { expect } from '@playwright/test'

export class {Domain}sPage {
  readonly page:         Page
  readonly createButton: Locator
  readonly searchInput:  Locator
  readonly successToast: Locator

  constructor(page: Page) {
    this.page         = page
    this.createButton = page.getByRole('link', { name: /créer/i })
    this.searchInput  = page.getByLabel('Rechercher')
    this.successToast = page.locator('.v-snackbar').filter({ hasText: /succès/i })
  }

  async goto()              { await this.page.goto('/{domain}s') }
  async gotoCreate()        { await this.page.goto('/{domain}s/create') }
  async gotoShow(id: number){ await this.page.goto(`/{domain}s/${id}/show`) }
  async gotoEdit(id: number){ await this.page.goto(`/{domain}s/${id}/edit`) }

  async getCards()          { return this.page.locator('.v-card').all() }

  async clickShow(i = 0) {
    (await this.getCards())[i].getByRole('button', { name: /voir/i }).click()
  }
  async clickEdit(i = 0) {
    (await this.getCards())[i].getByRole('button', { name: /éditer/i }).click()
  }
  async clickDelete(i = 0) {
    (await this.getCards())[i].getByRole('button', { name: /supprimer/i }).click()
  }

  async confirmDelete() {
    await this.page.getByRole('dialog').getByRole('button', { name: /supprimer/i }).click()
  }

  async search(query: string) {
    await this.searchInput.fill(query)
    await this.page.waitForTimeout(400) // debounce 300ms
  }

  async expectSuccessToast() {
    await this.successToast.waitFor({ state: 'visible', timeout: 5000 })
  }

  async expectUrl(pattern: string | RegExp) {
    await expect(this.page).toHaveURL(pattern)
  }
}

// tests/e2e/{domain}s/list.spec.ts
import { test, expect } from '@playwright/test'
import { {Domain}sPage } from '../pages/{domain}s.page'

test.describe('Liste des {Domain}s', () => {

  test('affiche la page avec le bouton créer', async ({ page }) => {
    const p = new {Domain}sPage(page)
    await p.goto()
    await expect(page).toHaveURL('/{domain}s')
    await expect(p.createButton).toBeVisible()
  })

  test('redirige vers /login si non authentifié', async ({ page, context }) => {
    await context.clearCookies()
    await page.goto('/{domain}s')
    await expect(page).toHaveURL('/login')
  })

  test('la recherche filtre les résultats', async ({ page }) => {
    const p = new {Domain}sPage(page)
    await p.goto()
    const before = (await p.getCards()).length
    await p.search('zzz_inexistant_zzz')
    const after = await p.getCards()
    expect(after.length).toBeLessThanOrEqual(before)
  })

  test('le bouton créer navigue vers /create', async ({ page }) => {
    const p = new {Domain}sPage(page)
    await p.goto()
    await p.createButton.click()
    await expect(page).toHaveURL('/{domain}s/create')
  })

})

