test.describe('CRUD {Domain}', () => {

  // Créer un {domain} via API avant les tests (plus rapide que l'UI)
  // et le supprimer après pour garder la base propre
  let test{Domain}Id: number

  test.beforeAll(async ({ request }) => {
    const created = await createViaApi(request, '/{domain}s', {
      // Ajoute ici les champs requis pour créer un {Domain} de test
    })
