  test.afterAll(async ({ request }) => {
    if (test{Domain}Id) {
      await deleteViaApi(request, '/{domain}s', test{Domain}Id)
    }
  })

  test('affiche le détail via la page show', async ({ page }) => {
    const p = new {Domain}sPage(page)
    await p.gotoShow(test{Domain}Id)
    await expect(page).toHaveURL(`/{domain}s/${test{Domain}Id}/show`)
