    const p = new {Domain}sPage(page)
    await p.gotoCreate()

    // Ajoute ici le remplissage des champs spécifiques au modèle {Domain}
    // Exemple : await page.getByLabel('Nom').fill('Test E2E')

    await page.getByRole('button', { name: /enregistrer/i }).click()
    await expect(page).toHaveURL('/{domain}s', { timeout: 5000 })
    await p.expectSuccessToast()
  })

  test('édite un {domain} via le formulaire', async ({ page }) => {
    const p = new {Domain}sPage(page)
    await p.gotoEdit(test{Domain}Id)
    await expect(page).toHaveURL(`/{domain}s/${test{Domain}Id}/edit`)

    // Ajoute ici la modification d'un champ spécifique
    // Exemple : await page.getByLabel('Nom').fill('Nom modifié')

    await page.getByRole('button', { name: /enregistrer/i }).click()
    await expect(page).toHaveURL('/{domain}s', { timeout: 5000 })
    await p.expectSuccessToast()
  })

  test('supprime un {domain} avec confirmation', async ({ page }) => {
    // Créer un item dédié à la suppression pour ne pas casser les autres tests
    const toDelete = await createViaApi(page.request, '/{domain}s', {
      // Ajoute ici les champs requis
    })

    const p = new {Domain}sPage(page)
    await p.gotoShow(toDelete.id)
    await page.getByRole('button', { name: /supprimer/i }).click()
    await expect(page.getByRole('dialog')).toBeVisible()
    await p.confirmDelete()

    await expect(page).toHaveURL('/{domain}s', { timeout: 5000 })
    await p.expectSuccessToast()
  })

})
